    adults_t:"Para que todos nuestros invitados puedan relajarse y disfrutar plenamente, nuestra boda será exclusivamente para adultos.",
    count:"¿Zarpas con nosotros?",
    count_t:"Confírmanos para guardarte un lugar a bordo.",
    accept:"¡Zarpo!",
    decline:"No podré",
    modify:"Modificar confirmación",
    form_title:"Confirmación",
    form_att:"¿Asistirás?",
    form_yes:"Sí, asistiré",
